import React, { useState, useEffect } from 'react';
import axios from 'axios';
import moment from 'moment';

const AttendancePage = () => {
  const [allEmployees, setAllEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  const [filters, setFilters] = useState({
    department: 'All',
    startDate: moment().subtract(7, 'days').format('YYYY-MM-DD'),
    endDate: moment().format('YYYY-MM-DD'),
  });

  // 1. Fetch ALL employees from the backend when the component loads
  useEffect(() => {
    const fetchAllEmployees = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = response.data.results || response.data || [];
        setAllEmployees(employeesData);

        // 2. Automatically create a unique list of departments from the employee data
        const uniqueDepartments = [...new Set(employeesData.map(emp => emp.department))];
        setDepartments(uniqueDepartments);

      } catch (error) {
        console.error("Error fetching employees for attendance:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAllEmployees();
  }, []); // Runs only once on page load

  const handleFilterChange = (e) => {
    setFilters({ ...filters, [e.target.name]: e.target.value });
  };

  // 3. Simulate time logs for each real employee AND filter the results
  const filteredLogs = allEmployees.filter(employee => {
      const inDepartment = filters.department === 'All' || employee.department === filters.department;
      return inDepartment;
  }).map((employee, index) => {
      // This part simulates the log data for each employee that passes the filter
      const status = ['Present', 'Absent', 'On Leave', 'Discrepancy'][index % 4];
      return {
        id: `${employee.id}-${index}`, // Create a unique key
        employee: employee,
        date: moment(filters.endDate).subtract(index % 3, 'days').format('YYYY-MM-DD'), // Simulate varied dates
        clockIn: status === 'Present' || status === 'Discrepancy' ? `09:${String(index).padStart(2,'0')} AM` : '--:--',
        clockOut: status === 'Present' ? `05:${String(index*2).padStart(2,'0')} PM` : '--:--',
        status: status,
      };
  }).filter(log => {
      // Second filter pass for the date range
      const logDate = moment(log.date);
      const startDate = moment(filters.startDate);
      const endDate = moment(filters.endDate);
      return logDate.isBetween(startDate, endDate, 'day', '[]');
  });


  const getStatusBadge = (status) => { /* ... (same as before) ... */ };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Attendance Log</h1>
          <p className="text-sm text-subtext-light">Filter and review attendance records.</p>
        </div>
      </div>

      <div className="p-4 bg-card-light dark:bg-card-dark rounded-lg shadow-sm mb-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
          <div>
            <label className="block text-sm font-medium text-subtext-light">Department</label>
            <select name="department" value={filters.department} onChange={handleFilterChange} className="mt-1 w-full">
              <option value="All">All Departments</option>
              {/* 4. Dynamically populate the dropdown with real departments */}
              {departments.map(dept => (
                <option key={dept} value={dept}>{dept}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-subtext-light">Start Date</label>
            <input type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} className="mt-1 w-full" />
          </div>
          <div>
            <label className="block text-sm font-medium text-subtext-light">End Date</label>
            <input type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} className="mt-1 w-full" />
          </div>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark rounded-xl shadow-sm overflow-x-auto">
        <table className="w-full text-sm text-left">
          {/* ... (Table Head is the same) ... */}
          <tbody>
            {isLoading ? (
              <tr><td colSpan="5" className="text-center py-10 text-subtext-light">Loading employee data...</td></tr>
            ) : filteredLogs.length === 0 ? (
              <tr><td colSpan="5" className="text-center py-10 text-subtext-light">No records found for the selected filters.</td></tr>
            ) : (
              filteredLogs.map(log => (
                <tr key={log.id} className="border-b hover:bg-gray-50">
                  <td className="px-6 py-4 font-medium text-text-light dark:text-white">
                    {log.employee.firstName} {log.employee.lastName}
                  </td>
                  <td className="px-6 py-4">{log.date}</td>
                  <td className="px-6 py-4">{log.clockIn}</td>
                  <td className="px-6 py-4">{log.clockOut}</td>
                  <td className="px-6 py-4">{getStatusBadge(log.status)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const getStatusBadge = (status) => {
    // ... (same as before) ...
};

export default AttendancePage;
